public abstract class Shape {
    private Shape() {}                       // no subtypes outside this file

    public static final class Circle extends Shape {
        final double radius; /* ctor + area() */
    }
    public static final class Square extends Shape {
        final double side;   /* ctor + area() */
    }
    public abstract double area();           // or accept(Visitor) when operations grow
}
